<script setup>
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {CATEGORIES,LOCATIONS} from '../data/seed'
import {action,date,money,ui} from '../lib/ui'
import Icon from '../components/Icon.vue'
import LikeButton from '../components/LikeButton.vue'
import ProductCard from '../components/ProductCard.vue'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),market=useMarketStore(),selected=ref(0)
const product=computed(()=>market.product(route.params.id)),own=computed(()=>auth.user?.id===product.value?.sellerId)
const location=computed(()=>LOCATIONS.find(l=>l.id===product.value?.locationId))
const liked=computed(()=>auth.user&&market.userFavorites(auth.user.id).some(p=>p.id===route.params.id))
const inCart=computed(()=>auth.user&&market.userCart(auth.user.id).some(p=>p.id===route.params.id))
const recommendations=computed(()=>market.products.filter(p=>p.status==='available'&&p.id!==product.value?.id&&p.category===product.value?.category).slice(0,4))
function requireLogin(){if(auth.user)return true;router.push({path:'/login',query:{redirect:route.fullPath}});return false}
async function add(buy=false){if(!requireLogin())return;if(inCart.value){router.push('/cart');return}const result=await action(()=>market.addToCart(auth.user.id,product.value.id),'已放入购物车，喜欢就带走吧');if(result&&buy)router.push({path:'/cart',query:{buy:product.value.id}})}
function favorite(){if(requireLogin())action(()=>market.toggleFavorite(auth.user.id,product.value.id))}
function chat(){if(requireLogin())router.push({path:'/messages',query:{partner:product.value.sellerId,product:product.value.id}})}
</script>
<template><div v-if="product" class="page-width inner-page product-page"><div class="breadcrumb"><RouterLink to="/">首页</RouterLink><Icon name="chevron" :size="13"/><RouterLink to="/market">逛市集</RouterLink><Icon name="chevron" :size="13"/>{{CATEGORIES.find(c=>c.id===product.category)?.label}}</div><div class="detail-layout"><div class="detail-gallery"><div class="detail-main-image"><img :src="product.images[selected]||product.images[0]" :alt="product.title"/><span class="detail-photo-label"><Icon name="camera" :size="15"/>看看它原本的样子</span></div><div v-if="product.images.length>1" class="detail-thumbnails"><button v-for="(image,i) in product.images" :key="i" :class="{active:selected===i}" @click="selected=i"><img :src="image" :alt="`商品照片${i+1}`"/></button></div><div class="gallery-note"><Icon name="leaf" :size="16"/>旧物或许带着使用的痕迹，也带着认真生活的印记。</div></div><div class="detail-info"><span class="eyebrow">A LITTLE OLD, A LOT TO LOVE</span><div class="detail-tags"><span>{{product.condition}}</span><span v-for="tag in product.tags" :key="tag">{{tag}}</span></div><h1>{{product.title}}</h1><p class="detail-subtitle">{{product.story}}</p><div class="detail-price"><span><small>¥</small>{{money(product.price)}}</span><del>原价 ¥{{money(product.originalPrice)}}</del><span class="price-note">好物不贵，喜欢可贵</span></div><div class="detail-properties"><div><span>物品分类</span><strong>{{CATEGORIES.find(c=>c.id===product.category)?.label}}</strong></div><div><span>来自学院</span><strong>{{product.college}}</strong></div><div><span>交接地点</span><button class="text-link" @click="ui.mapLocation=product.locationId;ui.mapOpen=true"><Icon name="pin" :size="15"/>{{location?.name}}<Icon name="chevron" :size="13"/></button></div><div><span>发布时间</span><strong>{{date(product.createdAt)}}</strong></div></div><div class="detail-seller"><span class="avatar">{{product.sellerName?.slice(-2)}}</span><div><strong>{{product.sellerName}}</strong><small>{{product.college}} · 濂溪同学</small></div><span class="seller-badge"><Icon name="shield" :size="14"/>校园用户</span></div><div v-if="product.status!=='available'" class="notice"><Icon name="info" :size="18"/>{{({reserved:'这件好物已被预订，去看看其他心动吧。',sold:'这件好物已经找到新归宿啦。',offline:'这件商品暂时下架，无法购买。'})[product.status]}}</div><div v-if="own" class="detail-actions"><RouterLink v-if="!['reserved','sold'].includes(product.status)" :to="`/publish/${product.id}`" class="button primary large"><Icon name="edit" :size="18"/>编辑我的闲置</RouterLink><RouterLink to="/profile" class="button outline large">管理我的商品</RouterLink></div><div v-else class="detail-actions"><button class="button primary large" :disabled="product.status!=='available'" @click="add(true)">心动了，带它回家<Icon name="arrow" :size="18"/></button><button class="button outline large" :disabled="product.status!=='available'" @click="add(false)"><Icon name="cart" :size="18"/>{{inCart?'已加入 · 查看购物车':'加入购物车'}}</button><LikeButton :model-value="!!liked" @update:model-value="favorite"/></div><button v-if="!own" class="contact-seller" @click="chat"><Icon name="message" :size="18"/>还有想了解的？和卖家聊聊<Icon name="arrow" :size="15"/></button><div class="detail-safety"><Icon name="shield" :size="17"/><span>校园公共区域面交 · 当面验货 · 支付仅为课堂模拟</span></div></div></div><section class="detail-description"><div class="section-heading"><h2>关于这件好物</h2><span class="eyebrow">A STORY WORTH SHARING</span></div><p>{{product.description}}</p><blockquote v-if="product.story"><span>“</span>{{product.story}}<small>— {{product.sellerName}}</small></blockquote></section><section v-if="recommendations.length" class="related-section"><div class="section-heading"><div><span class="eyebrow">YOU MIGHT ALSO LOVE</span><h2>再多看一眼，也许会心动。</h2></div><RouterLink to="/market" class="text-link">继续逛逛<Icon name="arrow" :size="17"/></RouterLink></div><div class="product-grid"><ProductCard v-for="item in recommendations" :key="item.id" :product="item"/></div></section></div><div v-else class="page-width empty-state"><Icon name="box" :size="44"/><h1>这件物品已经离开了市集</h1><p>还有其他美好，等着与你相遇。</p><RouterLink to="/market" class="button primary">去逛逛其他闲置</RouterLink></div></template>
